'use strict';
const $ = s => document.querySelector(s);
const escapeHTML = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
const labels = {overview:'今日简报',goals:'我的目标', decisions:'决策空间',tasks:'行动清单',metrics:'观察与指标',review:'周期复盘',knowledge:'个人资料库',settings:'模型与设置'};
const states = {created:'待记录初始选择',baseline_recorded:'待参考建议',recommended:'待你确认',decided:'进行中',resolved:'已回看',abandoned:'已放下'};
const statusClass = s => s==='resolved'?'success':s==='decided'?'blue':s==='abandoned'?'muted':'pending';
let S = null, route = 'overview', period = 7, filter = 'all', modelBusy = false;
let toastTimer, lastPlannerSignature="";
let intakeDraft=null;
function toast(message, error=false) { const t=$('#toast');t.textContent=message;t.classList.toggle('error',error);t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',error?7000:3500); }
async function api(path, options={}) { const response=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json','X-QOne-Client':'web',...(options.headers||{})}}); let data;try{data=await response.json();}catch{throw new Error('服务暂时不可用，请确认本地程序正在运行');}if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'请求未完成，请检查输入后重试');return data; }
const post=(path,body)=>api(path,{method:'POST',body:JSON.stringify(body)});
const date=(v,short=false)=>v?new Date(v).toLocaleString('zh-CN',short?{month:'short',day:'numeric'}:{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'未设期限';
const domain=v=>S?.domains[v]||v;
const option=(d,id)=>d.options.find(o=>o.id===id)?.label||id;
const percent=v=>v===null||v===undefined?'—':Math.round(v*100)+'%';
function openDialog(title,html){ if(modelBusy)return;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal(); }
function closeDialog(){if(!modelBusy)$('#dialog').close();}
function empty(title,description,button='',wide=false){return `<div class="empty ${wide?'wide':''}"><div class="empty-symbol">◇</div><h3>${e(title)}</h3><p>${e(description)}</p>${button}</div>`;}
function button(label,action,extra='',primary=false){return `<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${label}</button>`;}
function head(title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">YOUR PERSONAL WORKSPACE</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;}
async function refresh(){S=await api('bootstrap?days='+period);render();}
function navigate(name){route=labels[name]?name:'overview';location.hash=route;toggleSidebar(false);render();window.scrollTo(0,0);}
function render(){if(!S)return;document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));$('#breadcrumb-title').textContent=labels[route];$('#decision-count').textContent=S.decisions.filter(d=>!['resolved','abandoned'].includes(d.status)).length;const pages={goals:goalsPage,overview:overviewPage,decisions:decisionsPage,tasks:tasksPage,metrics:metricsPage,review:reviewPage,knowledge:knowledgePage,settings:settingsPage};$('#main').innerHTML=(S.demo?'<div class="demo-banner">示例空间 · 所有内容均为合成记录，与个人真实数据分开存储</div>':'')+pages[route]();if(route==='overview')lastPlannerSignature=JSON.stringify(S.planner);if(route==='settings')loadProviders();}
function decisionRows(decisions){return decisions.map(d=>`<div class="decision-row"><div class="decision-marker">◇</div><div class="decision-main"><button class="decision-title" data-action="detail" data-id="${e(d.decision_id)}">${e(d.question)}</button><div class="row-meta"><span>${e(domain(d.domain))}</span><span>·</span><span>${date(d.deadline,true)} 回看</span>${d.recommendation?'<span>·</span><span>已参考模型</span>':''}</div></div><div class="card-end"><span class="tag ${statusClass(d.status)}">${e(states[d.status])}</span><button class="text-button" data-action="detail" data-id="${e(d.decision_id)}">查看 ↗</button></div></div>`).join('');}
function taskRows(tasks){return tasks.map(t=>`<div class="task-row ${t.done?'done':''}"><input type="checkbox" data-task="${e(t.id)}" ${t.done?'checked':''} aria-label="${e(t.title)}完成状态"><span class="task-title">${e(t.title)}</span><span class="tiny">${e(domain(t.domain))}</span>${t.decision_id?`<button class="text-button" data-action="detail" data-id="${e(t.decision_id)}">回看</button>`:''}</div>`).join('');}
function metricRows(){return S.scores.metrics.slice(0,4).map(m=>`<div class="metric-row"><div class="metric-head">${e(m.name)}<span>${m.latest_value===null?'待记录':e(m.latest_value)+' '+e(m.unit)}</span></div><div class="metric-track"><div class="metric-fill" style="width:${m.score===null?0:Math.round(m.score*100)}%"></div></div><div class="metric-bottom"><span>${m.n} / ${m.target_count} 次记录</span><span>${m.score===null?'尚无数据':'范围内得分 '+percent(m.score)}</span></div></div>`).join('');}
const icons = {
 overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 17h7m-3.5-3.5v7"/>',
 goals:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="m14 10 6-6"/>',
 decisions:'<path d="m12 3 9 9-9 9-9-9Z"/><path d="M8 12h8m-4-4v8"/>',
 tasks:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 9 2 2 5-5m-7 9h8"/>',
 metrics:'<path d="M4 4v16h16M8 15l4-5 4 2 4-7"/>',
 review:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2"/>',
 knowledge:'<path d="M4 4h6l2 2h8v14H4Z"/><path d="M8 11h8m-8 4h6"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>'
};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.tasks}</svg>`;}
function sourceLabel(c){if(c.source==='adaptive')return '个人历史预测';if(c.source==='scenario')return '显式假设推演';return c.source==='rules'?'规则草案':c.source.startsWith('laya:')?'Laya 排序':'本地模型提案';}
function goalFor(c){return S.goals.find(g=>g.id===c.goal_id);}
function recommendationEvidence(c){const g=goalFor(c);return `<details class="reason-disclosure"><summary>为什么推荐这一步 <span>＋</span></summary><div class="reason-content"><p>${e(c.reason)}</p>${c.kind==='system'?systemEvidence(c):''}${g?`<dl><dt>来自你的目标</dt><dd>${e(g.title)}</dd><dt>目标完成标准</dt><dd>${e(g.success_criterion)}</dd><dt>已知约束</dt><dd>优先级 ${g.priority}/5 · ${g.deadline?'目标期限 '+date(g.deadline):'未设置目标期限'}</dd></dl>`:''}<div class="provenance">来源：${e(c.source)}${c.run_id?' · 记录 '+e(c.run_id):''}<br>${['adaptive','scenario'].includes(c.source)?'先比较资源与目标取舍，再给出有条件的行动提案；预测仍需后续观察核验。':c.source==='rules'?'这是依据已有记录给出的规划草案，具体步骤仍可调整。':c.source.startsWith('laya:')?'Laya提供候选排序；执行说明沿用规划规则，效果待核验。':'步骤与时长由模型建议，尚未证明执行效果。'}</div></div></details>`;}
function evidenceIssueLabel(issue){const code=issue?.code||'';if(code==='observation_conflict')return '同一测量同一时点存在未解决冲突';if(code==='observation_superseded')return '引用的观察已被显式更正';if(code==='before_reference_not_current')return '事前引用不是行动开始时的当前观察';if(code.startsWith('before_state_'))return '行动开始时的事前状态不可用';return '证据不满足学习资格';}
function trainingEvidence(forecast){const evidence=forecast?.training_evidence;if(!evidence)return '';const summary=evidence.summary||{};const excluded=evidence.excluded_episodes||[];const rows=excluded.slice(0,4).map(item=>{const reasons=[...new Set((item.issues||[]).map(evidenceIssueLabel))].join('；');return `${e(item.episode_id)}：${e(reasons||'证据不满足学习资格')}`;}).join('<br>');const omitted=excluded.length>4?`<br>另有 ${excluded.length-4} 条未展开`:'';return `<dt>学习证据资格</dt><dd>可训练 ${e(summary.trainable_n??forecast.training_n)} 条 / 可用 ${e(summary.available_n??forecast.training_n)} 条；排除 ${e(summary.excluded_n??excluded.length)} 条。${rows?`<br>${rows}${omitted}`:'<br>没有发现冲突或失效引用。'}</dd>`;}
function systemEvidence(c){const s=S.planner.system;if(!s)return '';const forecast=c.system_forecast;return `<dl><dt>目标取舍</dt><dd>${s.goal_order.map(id=>e(s.goals.find(g=>g.id===id)?.title||id)).join(' → ')}</dd><dt>资源消耗上界</dt><dd>${Object.entries(c.system_costs||{}).map(([id,v])=>{const r=s.state.resources[id];return e(r?.name||id)+' '+e(v.upper)+' '+e(r?.unit||'');}).join('；')||'尚未声明'}</dd>${forecast?`<dt>历史支持</dt><dd>${forecast.training_n} 条可用结果；相同行动组合 ${forecast.portfolio_support} 条</dd>${trainingEvidence(forecast)}<dt>预测变化范围</dt><dd>${Object.entries(forecast.predictions).map(([mid,p])=>e(s.state.measures[mid]?.name||mid)+'：'+p.lower.toFixed(1)+' 至 '+p.upper.toFixed(1)+' '+e(p.unit)).join('；')}</dd><dt>预测含义</dt><dd>给定模型假设的边际预测范围，尚无真实个人收益或因果证明。</dd>`:''}</dl>`;}

function recommendationCard(c,i=0){const g=goalFor(c);if(i)return `<details class="alternative-brief"><summary><span class="alternative-index">0${i+1}</span><div><small>${e(c.system_dimension_name||domain(c.domain))} · ${e(sourceLabel(c))}</small><h3>${e(c.title)}</h3></div><span class="alternative-duration">${c.minutes}<small> min</small></span><b>＋</b></summary><div class="alternative-body"><p>${e(c.reason)}</p><dl><dt>第一步</dt><dd>${e(c.first_step||'具体操作待细化')}</dd><dt>完成标准</dt><dd>${e(c.done_when||'核对本次产出')}</dd></dl><div class="card-actions">${button('加入今日安排 ↗','accept-suggestion',`data-id="${e(c.id)}" data-proposal="${e(c.proposal_sha256)}"`,true)}${button('今天跳过','dismiss-suggestion',`data-id="${e(c.id)}" data-proposal="${e(c.proposal_sha256)}"`)}</div></div></details>`;return `<article class="action-brief ${i?'secondary-brief':'lead-brief'}"><div class="brief-cover"><div class="brief-kicker"><span><i></i> ${i?'接下来考虑':'建议优先处理'} <b>/ 0${i+1}</b></span><span class="duration">${c.minutes} <small>min</small></span></div><div class="brief-context">${e(c.system_dimension_name||domain(c.domain))}${g?' <span>/</span> '+e(g.title):''}</div><h2>${e(c.title)}</h2><p class="brief-reason">${e(c.reason)}</p><div class="brief-actions">${button(c.kind==='review'?'打开结果回看 ↗':i?'加入今日安排 ↗':'采纳，加入今日安排 ↗','accept-suggestion',`data-id="${e(c.id)}" data-proposal="${e(c.proposal_sha256)}"`,true)}<button class="quiet-button" data-action="dismiss-suggestion" data-id="${e(c.id)}" data-proposal="${e(c.proposal_sha256)}">今天跳过</button></div><div class="source-label"><span>${e(sourceLabel(c))}</span><span>由你确认后安排</span></div></div><div class="execution-brief"><div><span class="step-index">01</span><div><h3>先从这里开始</h3><p>${e(c.first_step||'具体操作待细化，可先查看推荐依据。')}</p></div></div><div><span class="step-index">02</span><div><h3>做到这里就可以停</h3><p>${e(c.done_when||'记录本次产出，再核对任务是否完成。')}</p></div></div></div>${recommendationEvidence(c)}</article>`;}
function todaySchedule(focused){return `<section class="schedule"><div class="section-heading"><div><span class="section-kicker">YOUR COMMITMENTS</span><h2>今日已安排 <span>${focused.filter(t=>t.done).length}/${focused.length}</span></h2></div><button class="text-button" data-route="tasks">全部行动 ↗</button></div>${focused.length?focused.map((t,i)=>`<div class="schedule-row ${t.done?'done':''}"><span class="schedule-order">${String(i+1).padStart(2,'0')}</span><input type="checkbox" data-task="${e(t.id)}" ${t.done?'checked':''} aria-label="${e(t.title)}完成状态"><div><span class="task-title">${e(t.title)}</span><small>${e(domain(t.domain))} · ${t.done?'已完成':'待你执行'}</small>${t.focus_recommendation?`<details><summary>查看行动说明</summary><p>开始：${e(t.focus_recommendation.first_step||'具体操作待细化')}</p><p>完成标准：${e(t.focus_recommendation.done_when||'核对本次产出')}</p></details>`:''}</div><span class="schedule-time">${t.focus_minutes||t.estimate_minutes||25}<small> min</small></span></div>`).join(''):`<div class="schedule-empty"><span>↳</span><p>采纳上方建议后，行动会出现在这里。<br><small>也可以直接记录你自己的安排。</small></p><button class="text-button" data-action="new-task">＋ 添加</button></div>`}</section>`;}
function planningRail(p){const active=p.system?p.system.goals.filter(g=>g.active!==false):S.goals.filter(g=>g.status==='active').sort((a,b)=>b.priority-a.priority);const total=S.settings.daily_available_minutes;const used=Math.max(0,total-p.available_minutes);const proposed=p.items.reduce((n,c)=>n+c.minutes,0);const free=Math.max(0,p.available_minutes-proposed);const observations=S.scores.observation_count;return `<aside class="planning-rail"><section class="capacity-card"><div class="rail-label">今日计划容量 <button class="text-button" data-route="settings" aria-label="调整每日计划容量">↗</button></div><div class="capacity-number">${p.available_minutes}<span>/ ${total} min</span></div><p>还可安排的时间</p><div class="capacity-bar" role="img" aria-label="已安排${used}分钟，建议${proposed}分钟，留白${free}分钟"><span style="width:${used/total*100}%"></span><span style="width:${proposed/total*100}%"></span></div><div class="capacity-legend"><span><i></i>已安排 <b>${used}</b></span><span><i></i>待采纳 <b>${proposed}</b></span><span><i></i>留白 <b>${free}</b></span></div><div class="capacity-footnote">按你设置的每日预算计算<br>不会自动占用日历或替你执行</div></section><section class="directions"><div class="rail-label">正在推进 <button class="text-button" data-route="goals">${active.length} 个目标 ↗</button></div>${active.slice(0,4).map((g,i)=>`<button class="direction-row" data-action="${p.system?'system-model':'edit-goal'}" data-id="${e(g.id)}"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${e(g.title)}</h3><p>${e(g.success_criterion)}</p><small>${p.system?e(p.system.state.goals[g.id]?.status==='met'?'条件已满足':p.system.state.goals[g.id]?.status==='not_met'?'条件尚未满足':'状态待确认'):e(domain(g.domain))+' <i>·</i> 优先级 '+g.priority+'/5'}</small></div><b>↗</b></button>`).join('')||'<p class="rail-empty">添加目标，给推荐一个方向。</p>'}<button class="add-direction" data-action="new-goal">＋ 添加目标</button></section><section class="signal-note"><span class="section-kicker">EVIDENCE, BEFORE ASSUMPTION</span><h3>让记录，校正下一次选择。</h3><p>${p.system?'当前 '+Object.values(p.system.state.measures).filter(m=>m.status==='known').length+' 个可用测量，'+p.system.episode_count+' 条行动结果记录。'+(p.system.synthetic?'此空间为合成示例。':'预测效果仍需后续核验。'):'近 '+period+' 天有 '+observations+' 条有效观察，'+S.report.resolved_decisions+' 个选择已回看。记录可供参考，尚不能证明因果关系。'}</p><button class="text-button" data-route="metrics">${p.system?'查看个人状态 ↗':'记录一次观察 ↗'}</button></section></aside>`;}
function systemReadiness(s){const result=s.comparison;const labels={needs_preference:'需要明确目标之间的取舍',no_feasible_plan:'当前约束下没有可推荐方案',equivalent_plans:'多个方案暂时无法区分',needs_goal_definition:'需要可检查的目标条件',conditional_preference:'当前优先方案不需要新增行动'};const issues=[...new Set(result.scenarios.flatMap(r=>r.issues.map(i=>systemIssue(i))))];return `<section class="setup-brief"><span class="section-kicker">${s.synthetic?'合成示例':'个人状态与行动比较'}</span><h2>${e(labels[result.choice_status]||'需要补充观察记录')}</h2><p>已比较 ${result.scenarios.length} 个方案，保留 ${result.frontier_ids.length} 个取舍候选。</p>${issues.length?'<ul>'+issues.slice(0,6).map(x=>'<li>'+e(x)+'</li>').join('')+'</ul>':''}<p>系统会保留未知，更新记录或明确取舍后重新比较。</p>${button('查看人生模型 ↗','system-model','',true)}</section>`;}
function systemIssue(i){return ({insufficient_history:'历史记录不足',portfolio_unsupported:'该行动组合缺少历史记录',target_baseline_unknown:'结果基线尚未记录或已过期',context_unknown:'当前状态尚未记录或已过期',context_interval_unsupported:'当前状态范围尚不支持此预测器',context_outside_observed_range:'当前状态超出历史观察范围',resource_unknown:'资源预算尚不明确或已过期',resource_exceeded:'行动消耗超过资源预算',guardrail_unknown:'无法核验底线条件',guardrail_violated:'方案违反底线条件',intermediate_guardrail_unmodeled:'尚不能预测过程中的底线变化',prerequisite_missing:'前置行动尚未完成',projection_outside_measure_domain:'预测超出测量有效范围'})[i.code]||'有影响假设需要核验';}
function autoFeed(p){
 if(!p)return '<div class="notice">正在读取推荐…</div>';
 const statuses={conditional:'已完成约束与目标比较 · 有条件推荐',needs_information:'尚不足以自动选择 · 查看缺失条件',idle:'暂无新的候选行动',pending:'规则草案已就绪 · 等待本地模型',running:'本地模型正在细化步骤',ready:'已根据当前记录更新',rules:'本地模型暂不可用 · 展示规则草案',error:'更新遇到问题',paused:'自动推荐已暂停'};
 const focused=S.tasks.filter(t=>t.focus_date===p.date);
 let recommendations;
 if(!p.enabled)recommendations=`<section class="setup-brief"><span class="section-kicker">ON YOUR TERMS</span><h2>自动推荐已暂停。</h2><p>已有的行动安排仍可继续。开启后，目标和记录变化会触发新的推荐。</p>${button('打开推荐设置 ↗','open-settings','',true)}</section>`;
 else if(p.items.length)recommendations=recommendationCard(p.items[0])+(p.items.length>1?'<section class="alternatives"><div class="alternatives-label">其他可选方向 <span>按本轮推荐顺序</span></div>'+p.items.slice(1).map((c,i)=>recommendationCard(c,i+1)).join('')+'</section>':'');
 else if(p.system)recommendations=systemReadiness(p.system);
 else if(p.has_goals)recommendations=`<section class="setup-brief"><span class="section-kicker">ROOM TO FOCUS</span><h2>${focused.some(t=>!t.done)?'先把手上的这一步做好。':'给今天留一点余地。'}</h2><p>${p.available_minutes<5?'今天的计划容量已经用完。你可以完成已安排的行动，或调整每日预算。':'当前没有新的候选行动。完成已安排事项、添加目标或更新记录后，系统会继续检查。'}</p>${button('查看今日行动 ↗','open-tasks','',true)}</section>`;
 else recommendations=`<section class="setup-brief"><span class="section-kicker">START WITH WHAT MATTERS</span><h2>你想把哪件事，<br>向前推进一步？</h2><p>写下一个目标，以及“怎样算完成”。<br>系统会自动提出下一步，你决定要不要做。</p>${button('写下第一个目标 ↗','new-goal','',true)}<div class="setup-example">例如：完成一个可以向别人演示的 Python 小工具。</div></section>`;
 return `<div class="brief-toolbar"><div class="planner-status ${p.status==='running'?'is-running':''}"><i></i>${e(statuses[p.status]||p.status)}${p.generated_at?'<span> · '+date(p.generated_at)+'</span>':''}</div><button class="text-button" data-action="refresh-planner">重新评估 ↻</button></div>${p.error?`<div class="notice warning">${e(p.error)}</div>`:''}<div class="brief-layout"><div class="brief-main">${recommendations}${todaySchedule(focused)}</div>${planningRail(p)}</div><div class="brief-bottom"><span>推荐是待验证的提案。行动结果会保留，目标达成需要你核对。</span>${p.limits?.goals_total>4?'<span>本轮使用前 4 个活跃目标</span>':''}</div>`;
}
function overviewPage(){const dateLabel=new Date(S.planner.date+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});return `<div class="brief-page-head"><div><div class="eyebrow">DAILY BRIEF <span>/</span> ${e(dateLabel)}</div><h1>让重要的事，向前一步<span>。</span></h1><p>从你的目标出发，给今天一个具体的行动方向。</p></div><button class="button" data-action="new-goal">＋ 添加目标</button></div><div id="auto-recommendations">${autoFeed(S.planner)}</div>`;}
function goalsPage(){if(S.planner.system){const s=S.planner.system;return head('目标与取舍','当前推荐依据人生模型中的目标条件、层级和取舍顺序。',button('查看或更新模型','system-model','',true))+`<div class="goals-register">${s.goals.map((g,i)=>`<article class="goal-register-row"><span class="goal-register-index">${String(i+1).padStart(2,'0')}</span><div class="goal-register-main"><h2>${e(g.title)}</h2><p>${e(g.success_criterion)}</p><div class="goal-register-meta"><span>${e(s.dimensions.find(d=>d.id===g.dimension_id)?.name||g.dimension_id)}</span><span>${e(({met:'条件已满足',not_met:'条件尚未满足',unknown:'状态待确认',inactive:'已暂停'})[s.state.goals[g.id]?.status]||'状态待确认')}</span>${g.parent_id?'<span>子目标 · '+e(s.goals.find(x=>x.id===g.parent_id)?.title||g.parent_id)+'</span>':''}</div></div>${button('查看模型 ↗','system-model')}</article>`).join('')}</div><p class="footnote">当前通过导入模型更新关联与测量口径。目标是否满足由观察条件判断，不以任务数量代替。</p>`;}const goals=[...S.goals].sort((a,b)=>(a.status==='active'?-1:1)-(b.status==='active'?-1:1)||b.priority-a.priority);return head('目标，决定前进的方向。','把完成标准写清楚，系统才能提出有边界的下一步。',button('＋ 新目标','new-goal','',true))+`<div class="goals-summary"><span><i></i>${goals.filter(g=>g.status==='active').length} 个进行中</span><span>${goals.filter(g=>g.status==='paused').length} 个已暂停</span><span>${goals.filter(g=>g.status==='completed').length} 个已完成</span></div><div class="goals-register">${goals.length?goals.map((g,i)=>{const related=S.tasks.filter(t=>t.goal_id===g.id);return `<article class="goal-register-row"><span class="goal-register-index">${String(i+1).padStart(2,'0')}</span><div class="goal-register-main"><div class="row-meta"><span>${e(domain(g.domain))}</span><span>·</span><span>${{active:'进行中',paused:'已暂停',completed:'已完成'}[g.status]}</span></div><h2>${e(g.title)}</h2><p>${e(g.success_criterion)}</p><div class="goal-register-meta"><span>优先级 <b>${g.priority}/5</b></span><span>${g.deadline?'目标期限 '+date(g.deadline,true):'未设定期限'}</span><span>${related.filter(t=>t.done).length}/${related.length} 项关联行动已完成</span></div></div><div class="goal-register-actions">${button('编辑 ↗','edit-goal',`data-id="${e(g.id)}"`)}${g.status==='active'?button('标记完成','goal-status',`data-id="${e(g.id)}" data-status="completed"`)+button('暂停','goal-status',`data-id="${e(g.id)}" data-status="paused"`):button('继续推进','goal-status',`data-id="${e(g.id)}" data-status="active"`)}</div></article>`;}).join(''):empty('写下第一个值得投入的目标','同时写明怎样算完成。保存后，系统会自动提出下一步。',button('添加目标','new-goal','',true),true)}</div>`;}
function goalForm(id=null){if(S.planner.system)return action('system-model');const g=id?S.goals.find(x=>x.id===id):{};openDialog(id?'调整目标':'你想完成什么？',`<form id="goal-form" data-id="${e(id||'')}" class="form-stack"><label>目标<input name="title" required maxlength="150" value="${e(g.title)}" placeholder="例如：四周内完成Python入门项目"></label><label>怎样算完成？<textarea name="success_criterion" rows="3" required maxlength="1000" placeholder="例如：独立完成并演示一个能运行的小程序">${e(g.success_criterion)}</textarea></label><div class="form-row"><label>领域<select name="domain">${Object.entries(S.domains).map(([v,t])=>`<option value="${v}" ${v===(g.domain||'learning')?'selected':''}>${t}</option>`).join('')}</select></label><label>优先级<select name="priority">${[5,4,3,2,1].map(v=>`<option value="${v}" ${v===(g.priority||3)?'selected':''}>${v}${v===5?' · 最重要':''}</option>`).join('')}</select></label></div><label>希望完成的时间 <small>可选</small><input name="deadline" type="datetime-local"></label><p class="form-note">保存后系统会自动生成建议。只推荐与已有目标相关的行动，由你决定是否采纳。</p><button class="button primary" type="submit">保存目标，自动获得推荐</button></form>`);if(g.deadline){const t=new Date(g.deadline);t.setMinutes(t.getMinutes()-t.getTimezoneOffset());$('#goal-form [name=deadline]').value=t.toISOString().slice(0,16);}}
function decisionsPage(){const list=S.decisions.filter(d=>filter==='all'||(filter==='active'?!['resolved','abandoned'].includes(d.status):d.status===filter));return head('把选择写清楚。','先记录你的判断，再参考建议，最后回看发生了什么。',button('＋ 新建决策','new-decision','',true))+`<div class="section-row"><div class="filters">${[['all','全部'],['active','进行中'],['resolved','已回看'],['abandoned','已放下']].map(([v,t])=>`<button class="chip ${filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><span class="tiny">${list.length} 个选择</span></div><section class="panel"><div class="panel-body">${list.length?decisionRows(list):empty('还没有这样的选择','写下问题、选项和回看标准，从低影响的日常选择开始。',button('新建决策','new-decision'),true)}</div></section>`;}
function tasksPage(){const pending=S.tasks.filter(t=>!t.done),done=S.tasks.filter(t=>t.done);return head('让想法落到行动。','确认后的选择会自动成为任务；完成勾选与决策结果分别记录。',button('＋ 添加任务','new-task','',true))+`<div class="full-grid"><section class="panel"><div class="panel-head"><h2>接下来要做 <small>${pending.length}</small></h2></div><div class="panel-body">${pending.length?taskRows(pending):empty('行动清单是空的','添加一个可以完成的小任务。')}</div></section><section class="panel"><div class="panel-head"><h2>已经完成 <small>${done.length}</small></h2></div><div class="panel-body">${done.length?taskRows(done):empty('留一点空间给进展','完成的任务会在这里保留。')}</div></section></div>`;}
function periodButtons(){return `<div class="filters">${[7,30,90].map(v=>`<button class="chip ${period===v?'active':''}" data-period="${v}">近${v}天</button>`).join('')}</div>`;}
function metricsPage(){if(S.planner.system){const s=S.planner.system;return head('个人状态与测量','保留不同单位、类别与原话；缺失、过期和冲突单独显示。',(s.mode==='adaptive'?button('登记当前观察','system-observation','',true)+button('登记行动结果','system-outcome'):'')+button('模型设置','system-model'))+`${s.synthetic?'<div class="notice warning">合成模型 · 仅供演示与工程验收，不是真实个人结果。</div>':''}<div class="full-grid">${Object.values(s.state.measures).map(m=>`<section class="large-card"><div class="row-meta"><span class="tag">${e(s.dimensions.find(d=>d.id===m.dimension_id)?.name||m.dimension_id)}</span><span>${e(({known:'已有观察',missing:'尚未记录',stale:'观察已过期',conflict:'记录存在冲突'})[m.status]||m.status)}</span></div><h3>${e(m.name)}</h3><div class="metric-big">${m.value===null?'—':typeof m.value==='object'?e(m.value.lower===m.value.upper?m.value.lower:m.value.lower+' 至 '+m.value.upper):e(m.value)} <small>${e(m.unit)}</small></div><p>${m.observed_at?'观察时间 '+date(m.observed_at):'等待按口径登记观察'}</p></section>`).join('')}</div>`;}return head('观察变化，不急着评价。','记录有定义、有单位的观察，缺失的数据保持为空。',button('＋ 定义指标','new-metric','',true))+`<div class="section-row">${periodButtons()}<span class="tiny">${S.scores.observation_count} 条有效记录</span></div>${S.scores.metrics.length?`<div class="full-grid">${S.scores.metrics.map(m=>`<section class="large-card"><div class="row-meta"><span class="tag">${e(domain(m.domain))}</span><span>${{higher:'越高越好',lower:'越低越好',target:'接近目标值'}[m.direction]}</span></div><h3 style="margin-top:15px">${e(m.name)}</h3><div class="metric-big">${m.latest_value===null?'—':e(m.latest_value)} <small>${e(m.unit)}</small></div><div class="metric-track"><div class="metric-fill" style="width:${m.score===null?0:Math.round(m.score*100)}%"></div></div><p>${m.n} 次观察 · 记录覆盖 ${percent(m.coverage)} · 参考范围 ${m.minimum}—${m.maximum}${m.direction==='target'?' · 目标 '+m.target:''}</p><div class="card-actions">${button('＋ 记录一次','new-observation',`data-id="${e(m.id)}"`,true)}${button('查看 / 更正记录','metric-history',`data-id="${e(m.id)}"`)}</div></section>`).join('')}</div>`:`<section class="panel">${empty('只追踪你真正关心的事','例如专注分钟、主观精力或恢复时间。定义后再开始记录。',button('定义第一个指标','new-metric','',true),true)}</section>`}<p class="footnote">指标版本在创建时固定；更换定义请新建指标。分数只是当前范围中的位置，不能用于诊断或衡量人的价值。</p>`;}
function reviewPage(){const r=S.report;const c=r.calibration;return head('把经历，变成下一次的线索。','看看完成了什么、哪些信息不足，以及接下来值得调整的一件事。')+`<div class="section-row">${periodButtons()}<span class="tiny">观察按窗口统计，决策报告为全部历史</span></div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>写一次复盘</h2></div><div class="panel-body"><ol class="review-questions"><li>这一段时间，哪一个选择达到了事前标准？</li><li>哪些判断缺少证据，哪些指标定义需要调整？</li><li>记录和模型建议，带来了帮助还是额外负担？</li><li>接下来，只想改变哪一件小事？</li></ol><form id="review-form" class="form-stack"><label>你的观察与下一步<textarea name="text" rows="7" maxlength="12000" required placeholder="不用写得完美。把发生的事、你的理解和下一步分别写下来。"></textarea></label><button class="button primary" type="submit">保存本次复盘</button></form></div></section><div><section class="panel"><div class="panel-head"><h2>决策过程报告</h2></div><div class="panel-body"><div class="metric-row"><div class="metric-head">已回看 / 所有选择<span>${r.resolved_decisions} / ${r.decisions}</span></div></div><div class="metric-row"><div class="metric-head">建议采用率<span>${percent(r.recommendation_adoption)}</span></div><div class="explanation">分母：${r.recommendation_adoption_n} 个曾收到建议的已决定事项</div></div><div class="metric-row"><div class="metric-head">可计分预测<span>${c.n}</span></div><div class="explanation">未计分 ${c.excluded} 条。分类推荐强度不是行动成功概率。</div></div><div class="metric-row"><div class="metric-head">Brier 概率损失<span>${c.brier_score===null?'暂无可计分预测':c.brier_score.toFixed(3)}</span></div></div><p class="explanation">采用率不等于建议正确率。只记录了实际选择的结果，未选方案的结果仍未知。</p></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>过去的复盘 <small>${S.reviews.length}</small></h2></div><div class="panel-body">${S.reviews.length?S.reviews.slice(0,8).map(v=>`<div class="review-history"><span class="tiny">${date(v.created_at)} · ${v.days}天观察窗口</span><p>${e(v.text)}</p></div>`).join(''):empty('第一次回看，从现在开始','你的复盘会和当时的数据快照一起保存。')}</div></section></div></div>`;}
function knowledgePage(){return head('给判断留下一份依据。','保存自己的项目要求、阅读笔记与约束。检索到的内容会在发送前展示。',button('＋ 添加资料','new-document','',true))+`<div class="notice">这里的资料由你提供，默认标记为未独立核实。模型只会收到当前问题相关的最多3段内容。</div>${S.documents.length?`<div class="full-grid">${S.documents.map(d=>`<section class="large-card"><span class="tag muted">用户资料 · 待核查</span><h3 style="margin-top:15px">${e(d.title)}</h3><p>${e(d.source)}</p><span class="tiny">${date(d.created_at)}</span><div class="card-actions">${button('阅读资料','document-detail',`data-id="${e(d.id)}"`)}${button('移除','delete-document',`data-id="${e(d.id)}"`)}</div></section>`).join('')}</div>`:`<section class="panel">${empty('把有用的背景放在这里','先添加一份与你当前目标有关的要求或笔记。',button('添加资料','new-document','',true),true)}</section>`}`;}
function settingsPage(){const s=S.settings;return head('把模型与数据放在掌握之中。','默认单用户、本机保存。云端调用需要先确认即将发送的内容。')+`<div class="settings-grid"><form id="settings-form" class="panel settings-form"><div class="panel-head"><h2>模型连接</h2><span class="tag">可替换</span></div><div class="panel-body form-stack"><div class="notice">自动推荐会检查目标、任务和记录的变化。导入人生模型后，由资源约束和状态预测比较方案；下方模型连接用于基础规划。</div><label class="check-label"><input name="auto_recommend_enabled" type="checkbox" ${s.auto_recommend_enabled?'checked':''}>开启自动推荐</label><label>自动推荐模型<select name="auto_recommend_provider"><option value="ollama" ${s.auto_recommend_provider==='ollama'?'selected':''}>本地Ollama · 生成小步骤</option><option value="laya" ${s.auto_recommend_provider==='laya'?'selected':''}>本地Laya · 排序已有候选</option></select></label><div class="form-row"><label>每日可安排时间（分钟）<input name="daily_available_minutes" type="number" min="5" max="480" value="${s.daily_available_minutes}" required></label><label>相同数据定期重评（分钟）<input name="auto_recommend_interval_minutes" type="number" min="15" max="1440" value="${s.auto_recommend_interval_minutes}" required></label></div><label>手动决策默认模型<select name="default_provider">${[['ollama','本地 Ollama · 生成建议'],['laya','本地 Laya · 类型化判断'],['cloud','云端兼容接口 · 生成建议']].map(([v,t])=>`<option value="${v}" ${s.default_provider===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="form-row"><label>Ollama 地址<input name="ollama_url" value="${e(s.ollama_url)}"></label><label>本地模型名称<input name="ollama_model" value="${e(s.ollama_model)}"></label></div><label>云端接口基础地址 <small>可选，通常以 /v1 结尾</small><input name="cloud_url" value="${e(s.cloud_url)}" placeholder="https://你的服务地址/v1"></label><div class="form-row"><label>云端模型名称<input name="cloud_model" value="${e(s.cloud_model)}" placeholder="按服务端支持的名称填写"></label><label>接口密钥 <small>${s.cloud_key_set?'已保存，留空保留':'尚未配置'}</small><input name="cloud_key" type="password" autocomplete="new-password" placeholder="仅保存到本机私有配置"></label></div><label>Laya 权重位置 <small>可选；留空使用固定版本的 Hugging Face 缓存</small><input name="laya_model_path" value="${e(s.laya_model_path)}" placeholder="本地完整权重目录"></label><div class="form-row"><label>Laya 设备<select name="laya_device"><option value="cpu" ${s.laya_device==='cpu'?'selected':''}>CPU · 与其他模型分开占用</option><option value="cuda" ${s.laya_device==='cuda'?'selected':''}>CUDA · 需要支持的显卡</option></select></label><label class="check-label"><input name="clear_cloud_key" type="checkbox">清除已保存云端密钥</label></div><div class="form-note">密钥不回传到页面或备份。不要把密钥写进问题、笔记或项目资料。</div><button class="button primary" type="submit">保存连接设置</button></div></form><div><section class="panel"><div class="panel-head"><h2>连接状态</h2><button class="text-button" data-action="check-providers">刷新 ↻</button></div><div class="panel-body" id="providers-status"><p class="explanation">正在检查本地连接…</p></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>人生模型与备份</h2></div><div class="panel-body"><p class="subtitle">数据保存在本机。私有备份包含原始文本，请保存在可信位置；摘要导出会去除自由文本与精确时间。</p><div class="card-actions">${button('查看或导入人生模型','system-model')}<a class="button" href="/api/export" download>导出脱敏摘要 ↗</a><a class="button" href="/api/backup" download>下载私有备份 ↓</a>${button('从备份恢复','restore')}</div><p class="footnote">恢复只允许写入空数据目录，现有数据不会被覆盖。脱敏摘要仍可能敏感，分享前请自行检查。</p></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>最近模型调用</h2></div><div class="panel-body">${S.runs.length?`<div class="runs"><table><thead><tr><th>模型</th><th>状态</th><th>时间</th></tr></thead><tbody>${S.runs.slice(0,8).map(r=>`<tr><td>${e(r.provider)}</td><td>${r.status==='completed'?'已完成':'未成功'}</td><td>${r.duration_ms?Math.round(r.duration_ms/1000)+'秒':'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有模型调用','真实调用和失败会单独记录，不会用模拟结果替代。')}</div></section></div></div>`;}
async function loadProviders(){try{const p=await api('providers');const el=$('#providers-status');if(!el)return;el.innerHTML=`<div class="model-provider">Ollama<span>${p.ollama.available?'已连接 · '+p.ollama.models.length+'个模型':'未连接'}</span></div><div class="model-provider">Laya<span>${p.laya.installed?'推理库已安装 · 运行时加载权重':'尚未安装推理库'}</span></div><div class="model-provider">云端模型<span>${p.cloud.configured?'已配置 · 调用前需确认':'可选配置'}</span></div><p class="explanation">安装或连接可用不等于模型已通过任务验收。</p>`;}catch(err){toast(err.message,true);}}
function newDecision(){openDialog('把一个选择写下来',$('#decision-form').innerHTML);const deadline=new Date(Date.now()+24*3600*1000);deadline.setMinutes(deadline.getMinutes()-deadline.getTimezoneOffset());$('#create-decision [name=deadline]').value=deadline.toISOString().slice(0,16);const text=$('#create-decision [name=options]');text.addEventListener('input',()=>{const choices=text.value.split('\n').map(x=>x.trim()).filter(Boolean);$('#create-decision [name=baseline_option_id]').innerHTML=choices.map((x,i)=>`<option value="o${i+1}">${e(x)}</option>`).join('');});}
async function detail(id){const d=await api('decisions/'+encodeURIComponent(id));const chosen=d.human_decision?.option_id;const r=d.recommendation;openDialog('决策详情',`<div class="row-meta"><span class="tag">${e(domain(d.domain))}</span><span class="tag ${statusClass(d.status)}">${states[d.status]}</span><span>${date(d.deadline)} 回看</span></div><h2 class="detail-question" style="margin-top:15px">${e(d.question)}</h2><div class="detail-section"><h3>事前成功标准</h3><p>${e(d.success_criterion)}</p></div>${d.context?`<div class="detail-section"><h3>背景与约束</h3><p>${e(d.context)}</p></div>`:''}<div class="detail-section"><h3>备选方案</h3><div class="option-list">${d.options.map(o=>`<div class="option ${chosen===o.id?'selected':''}"><span>${e(o.label)}</span><span class="row-meta">${d.baseline?.option_id===o.id?'初始选择':''}${chosen===o.id?' · 最终选择':''}</span></div>`).join('')}</div></div>${r?`<div class="recommendation"><span class="tag success">模型参考建议</span><h3 style="margin-top:12px">${e(option(d,r.option_id))}</h3><p>${e(r.rationale)}</p><div class="explanation">来源 ${e(r.source)} · 推荐强度 ${percent(r.confidence)}（未校准）<br>该强度不是行动成功率。${r.evidence_ids?.length?'使用资料 '+r.evidence_ids.length+' 份。':''}</div></div>`:''}${d.outcome?`<div class="detail-section"><h3>回看结果</h3><p>${{yes:'达到了标准',no:'未达到标准',partial:'部分达到',unknown:'尚无法判断'}[d.outcome.success]}</p><p>${e(d.outcome.notes)}</p></div>`:''}${d.status==='created'?`<form id="baseline-form" data-id="${e(id)}" class="form-stack"><label>先保存你自己的初始选择<select name="option_id">${d.options.map(o=>`<option value="${e(o.id)}">${e(o.label)}</option>`).join('')}</select></label><button class="button primary" type="submit">保存初始判断</button></form>`:''}${d.status==='baseline_recorded'?`<div class="detail-section"><h3>参考一个模型的判断</h3><div class="form-stack"><select id="recommend-provider">${[['ollama','本地 Ollama'],['laya','本地 Laya'],['cloud','云端兼容接口']].map(([v,t])=>`<option value="${v}" ${S.settings.default_provider===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="inline-actions">${button('预览内容并获取建议','recommend',`data-id="${e(id)}"`,true)}</div><p class="explanation">也可以直接确认自己的选择。模型不会替你执行。</p></div>`:''}${['baseline_recorded','recommended'].includes(d.status)?`<form id="decide-form" data-id="${e(id)}" class="form-stack"><label>你最终决定<select name="option_id">${d.options.map(o=>`<option value="${e(o.id)}" ${d.baseline?.option_id===o.id?'selected':''}>${e(o.label)}</option>`).join('')}</select></label><label>你的理由 <small>${d.risk==='high'||!d.reversible?'此选择需要填写理由':'可选'}</small><input name="reason" ${d.risk==='high'||!d.reversible?'required':''} placeholder="保留自己的取舍依据"></label><button class="button primary" type="submit">确认选择，加入行动清单</button></form>`:''}${d.status==='decided'?`<form id="resolve-form" data-id="${e(id)}" class="form-stack"><label>对照事前标准，实际结果如何？<select name="success"><option value="yes">达到了标准</option><option value="no">未达到标准</option><option value="partial">部分达到</option><option value="unknown">尚无法判断</option></select></label><label>实际发生了什么？<textarea name="notes" rows="3" placeholder="保留结果与事后观察，不改写事前标准"></textarea></label><button class="button primary" type="submit">保存回看结果</button></form>`:''}${!['resolved','abandoned'].includes(d.status)?`<div class="inline-actions">${button('放下这次选择','abandon',`data-id="${e(id)}"`)}</div>`:''}<details class="detail-section"><summary class="tiny">查看事件记录 · ${d.events.length} 条</summary>${d.events.map(v=>`<div class="detail-event">${v.seq} · ${date(v.ts)} · ${e(v.type)}<br>记录哈希 ${e(v.hash.slice(0,16))}…</div>`).join('')}</details>`);}
function newTask(){openDialog('添加一小步行动',`<form id="task-form" class="form-stack"><label>任务名称<input name="title" required maxlength="300" placeholder="写下一件可以实际完成的事"></label><div class="form-row"><label>领域<select name="domain">${Object.entries(S.domains).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>计划完成时间 <small>可选</small><input name="deadline" type="datetime-local"></label></div><div class="form-row"><label>预计投入（分钟）<input name="estimate_minutes" type="number" min="5" max="480" value="25" required></label><label>任务优先级<select name="priority">${[5,4,3,2,1].map(v=>`<option value="${v}" ${v===3?'selected':''}>${v}</option>`).join('')}</select></label></div><label>关联目标 <small>可选</small><select name="goal_id"><option value="">独立任务</option>${S.goals.filter(g=>g.status==='active').map(g=>`<option value="${e(g.id)}">${e(g.title)}</option>`).join('')}</select></label><button class="button primary" type="submit">加入行动清单</button></form>`);}
function newMetric(){openDialog('定义一个值得观察的指标',`<form id="metric-form" class="form-stack"><label>指标名称<input name="name" required maxlength="80" placeholder="例如：专注时间、主观精力"></label><div class="form-row"><label>所属领域<select name="domain">${Object.entries(S.domains).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>单位<input name="unit" value="分钟" required maxlength="20"></label></div><div class="form-row"><label>最小值<input name="minimum" type="number" value="0" step="any" required></label><label>最大值<input name="maximum" type="number" value="120" step="any" required></label></div><label>怎样理解这个数值<select name="direction"><option value="higher">越高越符合目标</option><option value="lower">越低越符合目标</option><option value="target">接近目标值</option></select></label><div class="form-row"><label>目标值 <small>仅目标型指标使用</small><input name="target" type="number" value="60" step="any"></label><label>每个窗口期望记录次数<input name="target_count" type="number" min="1" max="365" value="7" required></label></div><div class="form-note">选择一个有意义的范围，观察定义会保留。更改定义时新建指标，避免历史数据被重新解释。</div><button class="button primary" type="submit">创建指标</button></form>`);}
function observationForm(id,old=null){const m=S.scores.metrics.find(x=>x.id===id);openDialog(old?'更正一次观察':'记录 · '+m.name,`<form id="observation-form" data-id="${e(id)}" data-supersedes="${e(old?.id||'')}" class="form-stack"><label>${e(m.name)}（${e(m.unit)}）<input name="value" type="number" min="${m.minimum}" max="${m.maximum}" step="any" required value="${old?e(old.value):''}"></label><label>观察时间<input name="observed_at" type="datetime-local" required></label><label>来源<input name="source" value="${e(old?.source||'自我记录')}"></label><label>补充说明 <small>可选</small><textarea name="note" rows="3">${e(old?.note||'')}</textarea></label><div class="form-note">${old?'更正后保留原记录的引用，统计只使用最新版本。':'缺少记录时保持为空，无需补猜。'}</div><button class="button primary" type="submit">保存观察</button></form>`);const t=new Date(old?.observed_at||Date.now());t.setMinutes(t.getMinutes()-t.getTimezoneOffset());$('#observation-form [name=observed_at]').value=t.toISOString().slice(0,16);}
function history(id){const m=S.scores.metrics.find(x=>x.id===id);openDialog(m.name+' · 最近记录',m.rows.length?m.rows.map(o=>`<div class="metric-row"><div class="metric-head"><strong>${e(o.value)} ${e(m.unit)}</strong><span>${date(o.observed_at)}</span></div><p class="subtitle">${e(o.note||o.source)}</p><div class="card-actions">${button('更正','correct-observation',`data-metric="${e(id)}" data-id="${e(o.id)}"`)}</div></div>`).join(''):empty('当前窗口还没有记录','先记录一次观察。'));}
function newDocument(){openDialog('添加个人资料',`<form id="document-form" class="form-stack"><label>标题<input name="title" required maxlength="150" placeholder="例如：项目交付要求"></label><label>来源 <small>网址、文件名或个人记录</small><input name="source" value="个人记录" maxlength="1000"></label><label>正文<textarea name="content" rows="9" maxlength="30000" required placeholder="粘贴你希望在决策时参考的材料。不要填写密钥。"></textarea></label><div class="form-note">资料保存在本机。默认不会被视为已经独立核实的事实。</div><button class="button primary" type="submit">保存到资料库</button></form>`);}
async function recommendPreview(id){const provider=$('#recommend-provider').value;const p=await post('decisions/'+id+'/preview',{provider,use_evidence:true});openDialog('确认这次模型参考',`<div class="notice ${p.remote?'warning':''}">${p.remote?'这次会发送到你配置的远程模型。请检查下面的内容后再确认。':'这次使用本机模型。只有当前选择与相关资料片段会进入模型。'}</div><p class="explanation">模型：${e(p.model)}<br>服务：${e(p.endpoint)}</p><pre class="preview">${e(JSON.stringify(p.context,null,2))}</pre><p class="explanation">${p.evidence_ids.length?'将参考 '+p.evidence_ids.length+' 份用户资料。':'未找到匹配的个人资料。'}建议仍需你自己确认。</p><button id="confirm-recommend" class="button primary full">${p.remote?'确认发送并获取建议':'开始本地推理'}</button>`);$('#confirm-recommend').addEventListener('click',async()=>{modelBusy=true;$('#dialog-body').innerHTML='<div class="progress-note"><div class="spinner"></div><p>模型正在比较当前选项…</p><p class="explanation">本地模型首次加载可能需要约一分钟。你的原始判断已经保存。</p></div>';try{await post('decisions/'+id+'/recommend',{provider,use_evidence:true,remote_confirmed:p.remote,snapshot_sha256:p.snapshot_sha256});modelBusy=false;await refresh();await detail(id);toast('建议已保存，请确认你自己的选择');}catch(err){modelBusy=false;$('#dialog-body').innerHTML=`<div class="failure">${e(err.message)}</div><p class="footnote">没有用模拟结果替代。你仍可手动确认，或检查设置后重试。</p>${button('回到决策','detail',`data-id="${e(id)}"`)}`;await refresh();}});}
function quantityInputs(measures){return measures.map(m=>`<label>${e(m.name)} · ${e(m.unit)}<input type="number" step="any" data-measure="${e(m.id)}" required ${m.scale==='ratio'?'min="0"':''}><small>${e(m.definition)}</small></label>`).join('');}
function readQuantities(form){return Object.fromEntries([...form.querySelectorAll('[data-measure]')].map(input=>{if(!input.value.trim()||!Number.isFinite(Number(input.value)))throw new Error('请填写实际测量数值；不清楚时保持未知');return [input.dataset.measure,Number(input.value)];}));}
function actionInputs(a,resources){return (a.costs||[]).map(c=>{const r=resources.find(r=>r.id===c.resource_id);const v=typeof c.amount==='object'?c.amount.lower+' 至 '+c.amount.upper:c.amount;return e(r?.name||c.resource_id)+' '+e(v)+' '+e(c.unit);}).join('；')||'尚未声明资源投入';}
async function systemObservationForm(){
 const current=(await api('system')).current;if(!current?.model.learning)throw new Error('请先导入定义了学习测量的人生模型');
 const ids=[...new Set([...current.model.learning.context_features,...current.model.learning.targets].map(d=>d.measure_id))];
 intakeDraft={kind:'observation',event_id:crypto.randomUUID(),parent_revision:current.id};
 openDialog('登记当前观察',`<form id="system-observation-form" class="form-stack"><p>按原来的定义与单位记录实际数量。登记后可作为后续结果窗口的事前观察；不会事后补成过去已经知道的数据。</p>${current.model.synthetic?'<div class="notice warning">这是合成示例空间，请只登记演示数据。</div>':''}<label>实际测量时刻<input name="observed_at" type="datetime-local" step="1" required></label>${quantityInputs(current.model.measures.filter(m=>ids.includes(m.id)))}<label>观察来源<textarea name="source" required maxlength="1000" placeholder="例如：本人按原验收标准清点的数量"></textarea></label><button class="button primary" type="submit">保存到本地观察</button><p class="form-note">没有测量值时请保留未知，不能用完成勾选或模型评价代替。</p></form>`);
}
async function systemOutcomeForm(){
 const current=(await api('system')).current;if(!current?.model.learning)throw new Error('请先导入定义了结果窗口的人生模型');
 intakeDraft=null;
 openDialog('登记行动结果 · 检查窗口',`<form id="system-outcome-window" class="form-stack"><p>结果对应 ${e(current.model.learning.horizon_days)} 天的固定观察窗口。请选择实际测量结果的时刻，再核对这段窗口内执行了哪些行动。</p>${current.model.synthetic?'<div class="notice warning">这是合成示例空间，请只登记演示数据。</div>':''}<label>实际结果测量时刻<input name="observed_at" type="datetime-local" step="1" required></label><fieldset><legend>窗口内按原定义完整执行的行动</legend>${current.model.actions.map(a=>`<label class="intake-choice"><input name="action_id" type="checkbox" value="${e(a.id)}"> ${e(a.title)} · ${e(a.minutes)} 分钟<br><small>${actionInputs(a,current.model.resources)}</small></label>`).join('')}</fieldset><p class="form-note">未勾选代表没有执行这些行动；部分执行时请保留原始观察，不登记为完整行动的学习结果。</p><button class="button primary" type="submit">检查事前观察与投入</button></form>`);
}
function showOutcomePreview(p){
 if(!p.eligible){openDialog('这段结果暂不能用于学习',`<div class="form-stack"><p>${p.issues.map(e).join('<br>')}</p><p>现在补录的观察不能当作过去已经知道的事实。可以先建立当前观察，供之后的结果窗口使用。</p>${button('登记当前观察','system-observation','',true)}${button('重新选择结果窗口','system-outcome')}</div>`);return;}
 intakeDraft={kind:'outcome',event_id:crypto.randomUUID(),parent_revision:p.revision,action_ids:p.action_ids,observed_at:p.observed_at,before:p.before,action_definition_sha256:p.action_definition_sha256};
 openDialog('登记行动结果 · 确认观察',`<form id="system-outcome-form" class="form-stack">${p.synthetic?'<div class="notice warning">合成示例验收 · 不是真实个人结果</div>':''}<p>观察窗口：${e(new Date(p.started_at).toLocaleString())} 至 ${e(new Date(p.observed_at).toLocaleString())}</p><h3>已有的事前观察</h3>${p.baselines.map(b=>`<p>${e(b.name)}：${e(b.value)} ${e(b.unit)}<br><small>实际测量 ${e(new Date(b.observed_at).toLocaleString())} · ${e(b.source)}</small></p>`).join('')}<h3>本窗口的行动与投入</h3>${p.actions.length?p.actions.map(a=>`<p>${e(a.title)} · ${e(a.minutes)} 分钟<br>${actionInputs(a,p.resources)}<br><small>第一步：${e(a.first_step)}<br>完成口径：${e(a.done_when)}</small></p>`).join(''):'<p>未执行这些行动，登记为无行动观察窗口。</p>'}<h3>实际结果数量</h3>${quantityInputs(p.targets)}<label>结果来源<textarea name="source" required maxlength="1000" placeholder="请说明如何按原口径获得这些结果"></textarea></label><label class="intake-choice"><input name="execution_confirmed" type="checkbox" required> 我已核对：行动选择完整反映实际执行情况，所选行动按展示的定义和投入完成，数值是该结果时点的实际测量。</label><button class="button primary" type="submit">确认并保存结果</button><p class="form-note">记录仍属本人报告，尚未独立核实。保存后可用于后续预测核验，不代表已证明行动因果效果。</p></form>`);
}
async function handleSubmit(event){const f=event.target;if(!(f instanceof HTMLFormElement))return;event.preventDefault();const data=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;try{if(f.id==='system-observation-form'){if(intakeDraft?.kind!=='observation')throw new Error('请重新打开观察登记');await post('system/observations',{event_id:intakeDraft.event_id,parent_revision:intakeDraft.parent_revision,observed_at:new Date(data.observed_at).toISOString(),values:readQuantities(f),source:data.source});intakeDraft=null;closeDialog();await refresh();toast('观察已保存在本地，可用于之后的结果窗口');}else if(f.id==='system-outcome-window'){const p=await post('system/outcomes/preview',{observed_at:new Date(data.observed_at).toISOString(),action_ids:new FormData(f).getAll('action_id')});showOutcomePreview(p);}else if(f.id==='system-outcome-form'){if(intakeDraft?.kind!=='outcome')throw new Error('请重新检查结果窗口');const result=await post('system/outcomes',{event_id:intakeDraft.event_id,parent_revision:intakeDraft.parent_revision,action_ids:intakeDraft.action_ids,observed_at:intakeDraft.observed_at,before:intakeDraft.before,action_definition_sha256:intakeDraft.action_definition_sha256,outcomes:readQuantities(f),source:data.source,execution_confirmed:f.elements.execution_confirmed.checked});intakeDraft=null;closeDialog();await refresh();toast(result.unchanged?'已确认此前保存的结果':'结果已保存，后续推荐会读取这条新证据');}else if(f.id==='goal-form'){const body={...data,priority:Number(data.priority),deadline:data.deadline?new Date(data.deadline).toISOString():null};await api('goals'+(f.dataset.id?'/'+f.dataset.id:''),{method:f.dataset.id?'PATCH':'POST',body:JSON.stringify(body)});closeDialog();await refresh();toast('目标已保存，系统正在自动推荐');}else if(f.id==='create-decision'){const choices=data.options.split('\n').map(x=>x.trim()).filter(Boolean);if(choices.length<2||choices.length>8)throw new Error('请填写2到8个备选方案');const d=await post('decisions',{...data,deadline:new Date(data.deadline).toISOString(),reversible:f.elements.reversible.checked,options:choices.map((x,i)=>({id:'o'+(i+1),label:x,expected_cost_hours:0})),baseline_option_id:data.baseline_option_id});closeDialog();await refresh();await detail(d.decision_id);toast('初始判断已保存');}else if(f.id==='task-form'){await post('tasks',{...data,estimate_minutes:Number(data.estimate_minutes),priority:Number(data.priority),deadline:data.deadline?new Date(data.deadline).toISOString():null});closeDialog();await refresh();toast('任务已加入清单');}else if(f.id==='metric-form'){await post('metrics',{...data,minimum:Number(data.minimum),maximum:Number(data.maximum),target:Number(data.target),target_count:Number(data.target_count)});closeDialog();await refresh();toast('指标已定义，可以开始观察');}else if(f.id==='observation-form'){await post('observations',{...data,metric_id:f.dataset.id,value:Number(data.value),observed_at:new Date(data.observed_at).toISOString(),supersedes:f.dataset.supersedes||null});closeDialog();await refresh();toast('观察已保存');}else if(f.id==='document-form'){await post('documents',data);closeDialog();await refresh();toast('资料已保存在本机');}else if(f.id==='review-form'){await post('reviews',{...data,days:period});await refresh();toast('复盘与数据快照已保存');}else if(f.id==='settings-form'){data.clear_cloud_key=f.elements.clear_cloud_key.checked;data.auto_recommend_enabled=f.elements.auto_recommend_enabled.checked;data.daily_available_minutes=Number(data.daily_available_minutes);data.auto_recommend_interval_minutes=Number(data.auto_recommend_interval_minutes);await post('settings',data);await refresh();toast('模型连接设置已保存');}else if(f.id==='baseline-form'){await post('decisions/'+f.dataset.id+'/baseline',data);await refresh();await detail(f.dataset.id);}else if(f.id==='decide-form'){await post('decisions/'+f.dataset.id+'/decide',data);closeDialog();await refresh();toast('已确认，行动已加入清单');}else if(f.id==='resolve-form'){await post('decisions/'+f.dataset.id+'/resolve',data);closeDialog();await refresh();toast('回看结果已保存');}else if(f.id==='abandon-form'){await post('decisions/'+f.dataset.id+'/abandon',data);closeDialog();await refresh();toast('已保留记录并放下这次选择');}}catch(err){toast(err.message,true);if(submit)submit.disabled=false;}}
async function action(name,el){if(name==='system-observation')return systemObservationForm();if(name==='system-outcome')return systemOutcomeForm();if(name==='system-model'){const data=await api('system');const current=data.current;openDialog('人生模型',`<div class="form-stack"><p>模型连接你的观察、目标、价值取舍、资源和行动。保留不同量表与原话，不合成人生总分。</p>${current?`<p>当前模型：${e(current.model.title)}${current.model.synthetic?' · 合成示例':''}</p><p>包含 ${current.model.dimensions.length} 个维度、${current.model.measures.length} 个测量定义、${(current.model.episodes||[]).length} 条行动结果记录。</p>`:'<p>尚未导入模型，目前使用基础目标规划。</p>'}<label>选择人生模型文件<input id="system-file" type="file" accept="application/json,.json"></label><p>导入前请核对观测口径、预算和目标取舍。合成示例仅用于体验。</p><button id="system-import" class="button primary">检查并导入</button></div>`);$('#system-import').addEventListener('click',async()=>{try{const file=$('#system-file').files[0];if(!file)throw new Error('请先选择文件');if(file.size>4*1024*1024)throw new Error('文件超过4MB');await post('system',{model:JSON.parse(await file.text()),parent_revision:current?.id||null});closeDialog();await refresh();toast('人生模型已导入，推荐将重新比较');}catch(err){toast(err.message,true);}});return;}if(name==='new-goal')return goalForm();if(name==='edit-goal')return goalForm(el.dataset.id);if(name==='goal-status'){await api('goals/'+el.dataset.id,{method:'PATCH',body:JSON.stringify({status:el.dataset.status})});await refresh();return toast('目标已更新，系统会重新推荐');}if(name==='refresh-planner'){await post('planner/refresh',{});return toast('已安排本地推荐更新');}if(name==='open-settings')return navigate('settings');if(name==='open-tasks')return navigate('tasks');if(name==='accept-suggestion'||name==='dismiss-suggestion'){const result=await post('planner/'+el.dataset.id+'/feedback',{action:name==='accept-suggestion'?'accept':'dismiss',proposal_sha256:el.dataset.proposal});await refresh();if(result.decision_id)await detail(result.decision_id);return toast(name==='accept-suggestion'?'已采纳，系统将调整后续推荐':'今天不再推荐这项行动');}if(name==='new-decision')return newDecision();if(name==='new-task')return newTask();if(name==='new-metric')return newMetric();if(name==='new-document')return newDocument();if(name==='detail')return detail(el.dataset.id);if(name==='new-observation')return observationForm(el.dataset.id);if(name==='metric-history')return history(el.dataset.id);if(name==='correct-observation'){const m=S.scores.metrics.find(x=>x.id===el.dataset.metric);return observationForm(m.id,m.rows.find(x=>x.id===el.dataset.id));}if(name==='recommend')return recommendPreview(el.dataset.id);if(name==='check-providers')return loadProviders();if(name==='abandon'){openDialog('放下这次选择',`<form id="abandon-form" data-id="${e(el.dataset.id)}" class="form-stack"><label>为什么暂时放下？<textarea name="reason" required rows="3"></textarea></label><p class="form-note">保留最初判断和已经发生的记录，避免把未知误记为失败。</p><button class="button primary" type="submit">保留记录并结束</button></form>`);return;}if(name==='document-detail'){const d=await api('documents/'+el.dataset.id);openDialog(d.title,`<div class="row-meta"><span class="tag">用户资料 · 未独立核实</span><span>${e(d.source)}</span></div><div class="preview" style="margin-top:20px;max-height:none">${e(d.content)}</div>`);return;}if(name==='delete-document'){if(!confirm('移除这份资料？之后不会再用于新的检索，已有建议中的引用ID会保留。'))return;await api('documents/'+el.dataset.id,{method:'DELETE'});await refresh();toast('资料已从本地库移除');return;}if(name==='restore'){openDialog('从私有备份恢复',`<div class="notice warning">仅能恢复到空数据空间。已有数据不会被覆盖；备份不包含接口密钥。</div><div class="form-stack"><label>选择 Q-One 私有备份<input id="restore-file" type="file" accept="application/json,.json"></label><button id="restore-confirm" class="button primary">检查并恢复</button></div>`);$('#restore-confirm').addEventListener('click',async()=>{try{const file=$('#restore-file').files[0];if(!file)throw new Error('请先选择备份文件');if(file.size>4*1024*1024)throw new Error('备份超过4MB，请使用完整本地备份流程');const backup=JSON.parse(await file.text());await post('restore',backup);closeDialog();await refresh();toast('备份已恢复');}catch(err){toast(err.message,true);}});}}
document.addEventListener('click',async event=>{const routeButton=event.target.closest('[data-route]');if(routeButton){event.preventDefault();navigate(routeButton.dataset.route);return;}if(event.target.closest('.close-dialog'))return closeDialog();const filterButton=event.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;return render();}const periodButton=event.target.closest('[data-period]');if(periodButton){period=Number(periodButton.dataset.period);try{await refresh();}catch(err){toast(err.message,true);}return;}const target=event.target.closest('[data-action]');if(target)try{await action(target.dataset.action,target);}catch(err){toast(err.message,true);}});
document.addEventListener('submit',handleSubmit);
document.addEventListener('change',async event=>{if(event.target.matches('[data-task]'))try{await api('tasks/'+event.target.dataset.task,{method:'PATCH',body:JSON.stringify({done:event.target.checked})});await refresh();}catch(err){toast(err.message,true);event.target.checked=!event.target.checked;}});
function toggleSidebar(open){$('.sidebar').classList.toggle('open',open);$('.sidebar').inert=window.innerWidth<=880&&!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));}
$('#menu-toggle').addEventListener('click',()=>toggleSidebar(!$('.sidebar').classList.contains('open')));
window.addEventListener('resize',()=>toggleSidebar(false));
document.addEventListener('click',event=>{if($('.sidebar').classList.contains('open')&&!event.target.closest('.sidebar')&&!event.target.closest('#menu-toggle'))toggleSidebar(false);});
document.querySelectorAll('.sidebar nav [data-route]').forEach(b=>{b.querySelector('span').innerHTML=icon(b.dataset.route);});
toggleSidebar(false);
$('#dialog').addEventListener('cancel',event=>{if(modelBusy)event.preventDefault();});
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1)||'overview';if(labels[name]){route=name;render();}});
route=labels[location.hash.slice(1)]?location.hash.slice(1):'overview';
refresh().catch(err=>{$('#main').innerHTML=`<div class="failure">${e(err.message)}</div>`;});

let plannerPolling=false;
setInterval(async()=>{if(!S||document.hidden||plannerPolling)return;plannerPolling=true;try{const p=await api('planner');S.planner=p;const el=$('#auto-recommendations');const signature=JSON.stringify(p);if(el&&!$('#dialog').open&&signature!==lastPlannerSignature){el.innerHTML=autoFeed(p);lastPlannerSignature=signature;}}catch{}finally{plannerPolling=false;}},5000);
